using System;
using System.Collections.Generic;
using System.Linq;

namespace Prometheus {
 public sealed class NestedContent0910 {
  public List<Clip> clips=new List<Clip>();
  public Dictionary<string,int> video_orders=new Dictionary<string,int>();
  public Dictionary<string,int> audio_orders=new Dictionary<string,int>();
 }
 public static partial class NestedMedia0910 {
  public const string Namespace="prometheus.nested-media";
  static Extension Data(Clip clip){return clip==null?null:clip.extensions.FirstOrDefault(x=>x!=null&&x.@namespace==Namespace&&x.version=="1");}
  public static bool IsNested(Project p,Clip clip){return clip!=null&&p!=null&&p.assets.Any(a=>a.id==clip.asset_id&&GeneratedMedia.Kind(a)=="nested")&&Data(clip)!=null;}
  public static NestedContent0910 Read(Clip clip){var ext=Data(clip);object raw;if(ext==null||ext.payload==null||!ext.payload.TryGetValue("content_json",out raw)||raw==null)return null;return Store.Json().Deserialize<NestedContent0910>(Convert.ToString(raw));}
  public static void Write(Clip clip,NestedContent0910 content){var ext=Data(clip);if(ext==null){ext=new Extension{@namespace=Namespace,version="1",payload=new Dictionary<string,object>()};clip.extensions.Add(ext);}ext.payload["content_json"]=Store.Json().Serialize(content);}
  public static void Validate(Project p,Clip outer){if(!IsNested(p,outer))return;var content=Read(outer);if(content==null||content.clips==null||content.clips.Count==0||content.video_orders==null||content.audio_orders==null)throw new Exception("Contenido del medio anidado inválido");var ids=new HashSet<string>();foreach(var child in content.clips){if(child==null||!ids.Add(child.id)||child.timeline_start==null||child.duration==null||child.source_in==null||child.speed==null||child.timeline_start.Seconds<0||child.duration.Seconds<=0||child.End>48*3600||child.asset_id==outer.asset_id)throw new Exception("Clip interno inválido");var asset=p.assets.Find(a=>a.id==child.asset_id);var stream=asset==null?null:asset.streams.Find(s=>s.id==child.stream_id);if(stream==null||(!content.video_orders.ContainsKey(child.track_id)&&!content.audio_orders.ContainsKey(child.track_id))||stream.kind=="audio"&&!content.audio_orders.ContainsKey(child.track_id)||stream.kind!="audio"&&!content.video_orders.ContainsKey(child.track_id))throw new Exception("Referencia interna del medio anidado inválida");if(child.source_in.Seconds<0||child.speed.Seconds<=0||stream.duration!=null&&child.source_in.Seconds+child.duration.Seconds*child.speed.Seconds>stream.duration.Seconds+0.000001&&!ShortTail.Allows(child,stream))throw new Exception("Recorte interno fuera de la fuente");ClipFraming.Validate(child);ClipKeyframes.Validate(child);EffectContracts.Validate(p,child,stream.kind=="audio"?"audio":"video");}}
  public static Clip CreateLegacy(Project p,IEnumerable<string> ids,string name){var selected=p.Active.clips.Where(c=>ids.Contains(c.id)).ToList();if(selected.Count<1)throw new Exception("Selecciona al menos un medio para anidar");var tracks=p.Active.tracks;foreach(var child in selected)if(tracks.Find(t=>t.id==child.track_id).locked)throw new Exception("Una pista seleccionada está bloqueada");var visual=selected.Where(c=>tracks.Find(t=>t.id==c.track_id).kind=="video").OrderByDescending(c=>tracks.Find(t=>t.id==c.track_id).order).FirstOrDefault();if(visual==null)throw new Exception("Selecciona al menos un medio de vídeo o imagen");double start=selected.Min(c=>c.timeline_start.Seconds),end=selected.Max(c=>c.End);var content=new NestedContent0910();foreach(var t in tracks.Where(t=>selected.Any(c=>c.track_id==t.id))){if(t.kind=="video")content.video_orders[t.id]=t.order;else content.audio_orders[t.id]=t.order;}foreach(var child in selected){var copy=Store.Json().Deserialize<Clip>(Store.Json().Serialize(Store.Fields(child)));copy.timeline_start=Rational.Time(child.timeline_start.Seconds-start);content.clips.Add(copy);}string id=Store.Id(),title=String.IsNullOrWhiteSpace(name)?"Medio anidado":name.Trim();var asset=new Asset{id=id,name=title,source=new MediaSource{kind="generated",uri="generated:"+id,resolver_type="nested",imported_at=DateTime.UtcNow.ToString("o")},presentation_origin=Rational.Time(0),recommended_duration=Rational.Frame(end-start),container_format="generated"};asset.streams.Add(new StreamInfo{id=Store.Id(),ordinal=0,kind="image",codec="nested",pts_origin=Rational.Time(0),time_base=new Rational(1,60),width=p.Active.width,height=p.Active.height});asset.extensions.Add(new Extension{@namespace=GeneratedMedia.Namespace,version="1",payload=new Dictionary<string,object>{{"kind","nested"},{"color_hex","303C49"},{"note",""}}});bool soleVisual=selected.Count(c=>tracks.Find(t=>t.id==c.track_id).kind=="video")==1;bool preferredFree=!p.Active.clips.Any(c=>!selected.Contains(c)&&c.track_id==visual.track_id&&c.timeline_start.Seconds<end-0.000001&&c.End>start+0.000001);var outer=new Clip{id=Store.Id(),name=title,asset_id=asset.id,stream_id=asset.streams[0].id,track_id=(soleVisual&&preferredFree?tracks.Find(t=>t.id==visual.track_id):FreeVideoTrack01024(p,selected,start,end)).id,timeline_start=Rational.Frame(start),duration=Rational.Frame(end-start),source_in=Rational.Time(0)};Write(outer,content);p.Active.clips.RemoveAll(c=>selected.Any(s=>s.id==c.id));p.Active.link_groups.RemoveAll(g=>g.clip_ids.Any(cid=>selected.Any(c=>c.id==cid)));p.Active.edit_groups.RemoveAll(g=>g.clip_ids.Any(cid=>selected.Any(c=>c.id==cid)));p.Active.transitions.RemoveAll(t=>selected.Any(c=>c.id==t.left_clip_id||c.id==t.right_clip_id));p.assets.Add(asset);p.Active.clips.Add(outer);return outer;}
  public static Project FlattenLegacy(Project original){if(!original.Active.clips.Any(c=>IsNested(original,c)))return original;var p=Store.Copy(original);var seq=p.Active;foreach(var track in seq.tracks)track.order*=100;int audioOrder=seq.tracks.Where(t=>t.kind=="audio").Select(t=>t.order).DefaultIfEmpty(0).Max()+1;foreach(var outer in seq.clips.Where(c=>IsNested(p,c)).ToList()){var content=Read(outer);var parentTrack=seq.tracks.Find(t=>t.id==outer.track_id);var mapping=new Dictionary<string,string>();foreach(var oldId in content.video_orders.OrderBy(pair=>pair.Value).Select(pair=>pair.Key)){string id=Store.Id();mapping[oldId]=id;seq.tracks.Add(new Track{id=id,name="Interna V",kind="video",order=parentTrack.order+1+content.video_orders[oldId],enabled=parentTrack.enabled});ConfigureInternalTrack(seq,oldId,seq.tracks.Last());}foreach(var oldId in content.audio_orders.OrderBy(pair=>pair.Value).Select(pair=>pair.Key)){string id=Store.Id();mapping[oldId]=id;seq.tracks.Add(new Track{id=id,name="Interna A",kind="audio",order=audioOrder++,enabled=parentTrack.enabled});ConfigureInternalTrack(seq,oldId,seq.tracks.Last());}double parentStart=outer.timeline_start.Seconds,parentIn=outer.source_in.Seconds,parentSpeed=outer.speed.Seconds,parentEnd=outer.End;foreach(var child in content.clips){double localStart=(child.timeline_start.Seconds-parentIn)/parentSpeed,localEnd=(child.End-parentIn)/parentSpeed,visibleStart=Math.Max(0,localStart),visibleEnd=Math.Min(outer.duration.Seconds,localEnd);if(visibleEnd<=visibleStart+0.000001)continue;var copy=Store.Json().Deserialize<Clip>(Store.Json().Serialize(Store.Fields(child)));copy.id=Store.Id();copy.track_id=mapping[child.track_id];copy.timeline_start=Rational.Time(parentStart+visibleStart);copy.duration=Rational.Time(visibleEnd-visibleStart);copy.source_in=Rational.Time(child.source_in.Seconds+(parentIn+visibleStart*parentSpeed-child.timeline_start.Seconds)*child.speed.Seconds);copy.speed=Rational.Time(child.speed.Seconds*parentSpeed);copy.enabled=copy.enabled&&outer.enabled;ApplyOuter(outer,copy,content.audio_orders.ContainsKey(child.track_id),parentTrack);seq.clips.Add(copy);}seq.clips.Remove(outer);}return p;}
 }
}






